function main({ data1, data2, data3 }) {
  const employeeMonth = data1; // 月份
  const employeeDay = data2;   // 日期
  const year = data3;          // 年份

  // 输入校验
  if (!Number.isInteger(employeeMonth) || employeeMonth < 1 || employeeMonth > 12) {
    throw new Error("data1（月份）必须是1-12之间的整数");
  }
  if (!Number.isInteger(employeeDay) || employeeDay < 1) {
    throw new Error("data2（日期）必须是正整数");
  }
  if (!Number.isInteger(year) || year < 1900 || year > 2100) {
    throw new Error("data3（年份）无效");
  }

  // 判断闰年
  const isLeap = (y) => (y % 4 === 0 && y % 100 !== 0) || y % 400 === 0;
  const febDays = isLeap(year) ? 29 : 28;
  const daysPerMonth = [31, febDays, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31];

  // 校验日期是否合法
  if (employeeDay > daysPerMonth[employeeMonth - 1]) {
    throw new Error(`日期 ${employeeMonth}月${employeeDay}日 在 ${year} 年无效`);
  }

  const totalDays = isLeap(year) ? 366 : 365;

  // 计算从1月1日到 employeeMonth/employeeDay（含）的天数
  let daysBefore = 0;
  for (let m = 0; m < employeeMonth - 1; m++) {
    daysBefore += daysPerMonth[m];
  }
  daysBefore += employeeDay;

  // 前段：按5天折算（1月1日 到 入职日，含）
  const leaveBefore = Math.floor((daysBefore / totalDays) * 5 * 10) / 10;

  // 后段：从入职日的**次日**到12月31日（不含入职日）
  const daysAfter = totalDays - daysBefore;

  // 后段：按10天折算
  const leaveAfter = Math.floor((daysAfter / totalDays) * 10 * 10) / 10;

  return {
    leaveBefore: Number(leaveBefore.toFixed(1)), // 确保显示为1位小数数字
    leaveAfter: Number(leaveAfter.toFixed(1))
  };
}

